  "sky",
  "modern-minimal",
  "violet-bloom",
  "t3-chat",
  "bubblegum",
  "doom-64",
  "amber-minimal",
  "supabase",
  "kodama-grove",
  "perpetuity",
  "cosmic-night",
  "claude",
  "mocha-mousse",
  "neo-brutalism",
  "notebook",
  "rose",
