/** Corner radius in px. `rounded` follows `--radius`. 4px is the control step; 0/8/16 sit on the 8px grid; 12 is the stock scale. */
export const RADII = [0, 4, 8, 12, 16] as const;
export type Radius = (typeof RADII)[number];
